package com.ruoyi.medical.persistence;
import com.ruoyi.medical.contracts.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Real 081 original witness/qualification ledger and real private Evaluation snapshot; storage remains explicit fixture. */
class ExpertSnapshotConsumerTest {
 @Test void suppliedActualSnapshotAvoidsOldPurposeRereadButKeepsWholeExpertLedger()throws Exception{try(var f=new ExpertFixture()){var qualification=f.author();f.approve(qualification);f.now=f.now.plusMinutes(1);var e=new ExpertEvaluationFixture(f);e.append();e.finish();var receipt=f.service.bindScore(f.f.subject,"1","snapshot-bind-key-001",e.bindRequest(qualification));var basis=f.schema.bind(receipt.path("record"),PermissionProtocol.Basis.class);f.transaction(()->{var snapshot=e.service.requireAcceptance(f.f.admission,e.definition.evaluation_id());doThrow(new AssertionError("old uniform-purpose lookup must not run")).when(f.evaluations).requireAcceptance(any(),anyString());var proof=f.authority.requireQualifiedScore(f.f.admission,basis,snapshot);assertEquals(e.scores.get(0),proof.score());proof.requireUnchanged();f.audits.clear();assertThrows(TenantAccessException.class,proof::requireUnchanged);return null;});}}
 @Test void snapshotFromPreviousTransactionCannotAuthorizeBindingRead()throws Exception{try(var f=new ExpertFixture()){var qualification=f.author();f.approve(qualification);f.now=f.now.plusMinutes(1);var e=new ExpertEvaluationFixture(f);e.append();e.finish();var receipt=f.service.bindScore(f.f.subject,"1","snapshot-bind-key-002",e.bindRequest(qualification));var basis=f.schema.bind(receipt.path("record"),PermissionProtocol.Basis.class);var snapshot=f.transaction(()->e.service.requireAcceptance(f.f.admission,e.definition.evaluation_id()));f.transaction(()->{assertThrows(TenantAccessException.class,()->f.authority.requireQualifiedScore(f.f.admission,basis,snapshot));return null;});}}
 @Test void changedOriginalScoreStillRejectedWithSuppliedSnapshot()throws Exception{try(var f=new ExpertFixture()){var qualification=f.author();f.approve(qualification);f.now=f.now.plusMinutes(1);var e=new ExpertEvaluationFixture(f);e.append();e.finish();var receipt=f.service.bindScore(f.f.subject,"1","snapshot-bind-key-003",e.bindRequest(qualification));var basis=f.schema.bind(receipt.path("record"),PermissionProtocol.Basis.class);f.transaction(()->{var snapshot=e.service.requireAcceptance(f.f.admission,e.definition.evaluation_id());e.status="FAILED";assertThrows(TenantAccessException.class,()->f.authority.requireQualifiedScore(f.f.admission,basis,snapshot));return null;});}}
}
